insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-07-23','nieuw','Inkoop','Bestellen vanuit de werkbegroting',
   'Vanuit de werkbegroting maak je nu met één klik een inkooporder of onderaannemerscontract in Bouw7, inclusief leverbon. Zo boekt een inkoopfactuur er straks automatisch op af. EVA groepeert per leverancier en bewakingscode; alleen geaccordeerde regels kunnen de deur uit. Nieuw is ook de knop "Winkel" bij materiaal: daarmee zet je een budgetreservering bij een leverancier neer in plaats van losse artikelen.'),
  ('2026-07-23','nieuw','Inkoop','Signalen op de Inkoop-tab',
   'De Inkoop-tab van een dossier waarschuwt nu bovenaan bij afwijkingen: als een leverancier of onderaannemer méér factureert dan er besteld is (handig om een creditnota op te vragen), en bij inkoopfacturen die aan geen enkele bestelling gekoppeld konden worden.');
